(()=>{
  const canvas=document.getElementById("drawingCanvas"),ctx=canvas.getContext("2d"),drawToggle=document.getElementById("drawToggle"),calculatorToggle=document.getElementById("calculatorToggle"),brushPanel=document.getElementById("brushPanel"),calculatorPanel=document.getElementById("calculatorPanel"),colorInput=document.getElementById("brushColor"),sizeInput=document.getElementById("brushSize"),sizeOutput=document.getElementById("brushSizeValue"),status=document.getElementById("drawingStatus");
  let drawing=false,last=null,brush="pencil",clearArmed=false,expression="";
  function resizeCanvas(){const copy=document.createElement("canvas");copy.width=canvas.width;copy.height=canvas.height;copy.getContext("2d").drawImage(canvas,0,0);const ratio=window.devicePixelRatio||1;canvas.width=Math.round(innerWidth*ratio);canvas.height=Math.round(innerHeight*ratio);canvas.style.width=`${innerWidth}px`;canvas.style.height=`${innerHeight}px`;ctx.setTransform(ratio,0,0,ratio,0,0);if(copy.width&&copy.height)ctx.drawImage(copy,0,0,copy.width,copy.height,0,0,innerWidth,innerHeight)}
  function setPanel(panel,button,open){panel.hidden=!open;button.setAttribute("aria-expanded",String(open));if(panel===brushPanel){canvas.classList.toggle("active",open);document.body.classList.toggle("drawing-active",open);status.textContent=open?"Đang viết trực tiếp lên đề. Đóng bảng bút để cuộn, chọn câu hoặc nhập đáp án.":""}if(open){const other=panel===brushPanel?calculatorPanel:brushPanel,otherButton=panel===brushPanel?calculatorToggle:drawToggle;other.hidden=true;otherButton.setAttribute("aria-expanded","false");if(other===brushPanel){canvas.classList.remove("active");document.body.classList.remove("drawing-active")}}}
  drawToggle.onclick=()=>setPanel(brushPanel,drawToggle,brushPanel.hidden);calculatorToggle.onclick=()=>setPanel(calculatorPanel,calculatorToggle,calculatorPanel.hidden);
  document.querySelectorAll("[data-close-panel]").forEach(button=>button.onclick=()=>{const panel=document.getElementById(button.dataset.closePanel),launcher=panel===brushPanel?drawToggle:calculatorToggle;setPanel(panel,launcher,false)});
  document.querySelectorAll("[data-brush]").forEach(button=>button.onclick=()=>{brush=button.dataset.brush;document.querySelectorAll("[data-brush]").forEach(item=>item.classList.toggle("active",item===button));status.textContent=brush==="eraser"?"Kéo qua nét hướng dẫn cần xóa.":brush==="highlighter"?"Kéo trực tiếp trên dòng hoặc hình cần nhấn mạnh.":"Bút chì sẵn sàng để khoanh, nối hoặc viết hướng dẫn trên đề."});
  sizeInput.oninput=()=>sizeOutput.textContent=`${sizeInput.value} px`;
  function point(event){const rect=canvas.getBoundingClientRect();return{x:event.clientX-rect.left,y:event.clientY-rect.top}}
  function begin(event){if(event.button!==undefined&&event.button!==0)return;drawing=true;last=point(event);canvas.setPointerCapture?.(event.pointerId);event.preventDefault()}
  function move(event){if(!drawing||!last)return;const next=point(event),size=Number(sizeInput.value);ctx.save();ctx.lineCap="round";ctx.lineJoin="round";ctx.lineWidth=brush==="eraser"?Math.max(12,size*2):size;if(brush==="eraser"){ctx.globalCompositeOperation="destination-out";ctx.strokeStyle="rgba(0,0,0,1)"}else{ctx.globalCompositeOperation="source-over";ctx.globalAlpha=brush==="highlighter"?.25:1;ctx.strokeStyle=colorInput.value}ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(next.x,next.y);ctx.stroke();ctx.restore();last=next;event.preventDefault()}
  function end(event){drawing=false;last=null;if(event?.pointerId!==undefined&&canvas.hasPointerCapture?.(event.pointerId))canvas.releasePointerCapture(event.pointerId)}
  canvas.addEventListener("pointerdown",begin);canvas.addEventListener("pointermove",move);canvas.addEventListener("pointerup",end);canvas.addEventListener("pointercancel",end);
  document.getElementById("clearDrawing").onclick=event=>{if(!clearArmed){clearArmed=true;event.currentTarget.classList.add("confirm");event.currentTarget.textContent="Nhấn lại để xóa hết";setTimeout(()=>{clearArmed=false;event.currentTarget.classList.remove("confirm");event.currentTarget.textContent="🗑 Xóa toàn bộ"},2500);return}ctx.clearRect(0,0,canvas.width,canvas.height);clearArmed=false;event.currentTarget.classList.remove("confirm");event.currentTarget.textContent="🗑 Xóa toàn bộ";status.textContent="Đã xóa toàn bộ nét hướng dẫn trên đề."};
  const display=document.getElementById("calculatorDisplay");
  function updateDisplay(value=expression||"0"){display.textContent=value}
  document.getElementById("calculatorKeys").onclick=event=>{const button=event.target.closest("button");if(!button)return;if(button.dataset.value){if(expression.length<80)expression+=button.dataset.value;updateDisplay();return}const action=button.dataset.calc;if(action==="clear"){expression="";updateDisplay()}else if(action==="backspace"){expression=expression.slice(0,-1);updateDisplay()}else if(action==="equals"){const safe=expression.replaceAll("÷","/").replaceAll("×","*").replaceAll("−","-");if(!safe||!/^[0-9+\-*/().%\s]+$/.test(safe)){updateDisplay("Lỗi");return}try{const result=Function(`"use strict";return (${safe})`)();if(!Number.isFinite(result))throw new Error();expression=String(Math.round((result+Number.EPSILON)*1e10)/1e10);updateDisplay()}catch{updateDisplay("Lỗi")}}};
  window.addEventListener("resize",resizeCanvas);resizeCanvas();
})();
